// Generated by scripts/build-admin.js; only served after administrator authorization.
export const adminAssets={"/admin/index.html":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex,nofollow\"><title>League of Doctors · Admin</title><link rel=\"stylesheet\" href=\"/play/play.css\"><link rel=\"stylesheet\" href=\"/play/landing.css\"><link rel=\"stylesheet\" href=\"/admin/admin.css\"><script src=\"/play/locales/ko.js\" defer></script><script src=\"/play/locales/en.js\" defer></script><script src=\"/play/locales/ja.js\" defer></script><script src=\"/play/locales/zh.js\" defer></script><script src=\"/play/locales/es.js\" defer></script><script src=\"/play/locales/it.js\" defer></script><script src=\"/play/locales/fr.js\" defer></script><script src=\"/play/i18n.js\" defer></script><script src=\"/admin/admin.js\" defer></script></head><body class=\"league-dark\"><header><a class=\"brand\" href=\"/\">League of Doctors</a><select id=\"language\" aria-label=\"Language\"><option value=\"ko\">한국어</option><option value=\"en\">English</option><option value=\"ja\">日本語</option><option value=\"zh\">简体中文</option><option value=\"es\">Español</option><option value=\"it\">Italiano</option><option value=\"fr\">Français</option></select></header><main class=\"admin-main\"><a href=\"/#ranking-panel\" data-i18n=\"leaderboard\"></a><h1 data-i18n=\"adminTitle\"></h1><p data-i18n=\"adminIntro\"></p><p id=\"admin-status\" role=\"status\" aria-live=\"polite\"></p><a id=\"admin-login\" class=\"button\" href=\"/api/auth/start\" hidden data-i18n=\"login\"></a><section id=\"admin-content\" hidden><div class=\"admin-actions\"><strong id=\"demo-count\"></strong><a href=\"/admin/new/\" class=\"button\" data-i18n=\"addDemo\"></a><button id=\"delete-demos\" class=\"danger\" data-i18n=\"deleteAllDemos\"></button><button id=\"reload-demos\" data-i18n=\"reloadDemos\"></button></div><div class=\"table-wrap\"><table><thead><tr><th data-i18n=\"nickname\"></th><th data-i18n=\"country\"></th><th data-i18n=\"average\"></th><th data-i18n=\"actions\"></th></tr></thead><tbody id=\"demo-rows\"></tbody></table></div></section></main></body></html>","type":"text/html; charset=utf-8"},"/admin/admin.css":{"content":".admin-main{max-width:1000px;margin:64px auto;padding:0 24px}.admin-main h1{font-size:clamp(1.8rem,4vw,3rem);margin:24px 0 12px}.admin-main>p{color:#aeb6c4;max-width:720px;line-height:1.7}.admin-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:30px 0 16px}.admin-actions strong{margin-right:auto}.admin-main table{width:100%;min-width:590px}.admin-main input{width:220px;max-width:100%;background:#161a21;color:#f0f1f3;border:1px solid #3c4350;border-radius:6px;padding:10px}.admin-main td{padding:12px}.admin-main td button{margin:3px}.admin-main header{gap:20px}#admin-status{min-height:1.5em}#admin-status.error{color:#ff9292}\r\nbody>header{position:static;background:#101113;border-bottom:1px solid #282b33;gap:20px;flex-wrap:wrap}body>header .brand{color:#f5f5f6;font-size:20px}#language{max-width:110px}\r\n\r\n.create-main{max-width:780px}.create-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.create-grid label{display:flex;flex-direction:column;gap:8px;color:#cdd2dc;font-size:14px}.create-grid input,.create-grid select{width:100%;padding:12px}.create-grid .full-width{grid-column:1/-1}.create-main form>p{line-height:1.7;margin:24px 0}.create-main form>button{min-width:180px}#create-status{min-height:1.5em}#create-status.error{color:#ff9292}#created-actions{margin-top:24px}@media(max-width:600px){.create-grid{grid-template-columns:1fr}.create-grid .full-width{grid-column:auto}}\r\n","type":"text/css; charset=utf-8"},"/admin/admin.js":{"content":"\"use strict\";\r\n(()=>{\r\n const I=LoDI18n,t=I.t,$=id=>document.getElementById(id);let entries=[],busy=false,loaded=false,statusKey=\"loading\";const drafts=new Map();\r\n function status(key,error=false){statusKey=key;$(\"admin-status\").textContent=t(key);$(\"admin-status\").classList.toggle(\"error\",error);}\r\n async function api(path,body){const response=await fetch(\"/api/\"+path,{credentials:\"same-origin\",method:body===undefined?\"GET\":\"POST\",headers:body===undefined?{}:{\"Content-Type\":\"application/json\"},body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(I.error(data.error));return data;}\r\n function render(){\r\n  $(\"demo-count\").textContent=t(\"demoCount\",{n:entries.length});$(\"delete-demos\").disabled=busy||!entries.length;$(\"reload-demos\").disabled=busy;$(\"demo-rows\").replaceChildren();\r\n  for(const e of entries){const row=document.createElement(\"tr\"),name=document.createElement(\"td\"),input=document.createElement(\"input\"),badge=document.createElement(\"span\");\r\n   input.value=drafts.get(e.id)??e.nickname;input.oninput=()=>{if(input.value===e.nickname)drafts.delete(e.id);else drafts.set(e.id,input.value);};input.maxLength=24;input.minLength=2;input.disabled=busy;input.setAttribute(\"aria-label\",t(\"nickname\")+\" · \"+e.nickname);badge.textContent=\" (demo)\";badge.className=\"demo-tag\";name.append(input,badge);row.append(name);\r\n   for(const value of [new Intl.DisplayNames([I.language],{type:\"region\"}).of(e.country),I.percent(e.average/100)]){const cell=document.createElement(\"td\");cell.textContent=value;row.append(cell);}\r\n   const actions=document.createElement(\"td\");\r\n   for(const [label,action] of [[\"saveNickname\",\"rename\"],[\"deleteDemo\",\"delete\"]]){const button=document.createElement(\"button\");button.textContent=t(label);button.disabled=busy;button.onclick=()=>{if(action===\"delete\"&&!confirm(t(\"deleteDemoConfirm\",{name:e.nickname})))return;mutate(\"admin/demos/\"+e.id+\"/\"+action,{nickname:input.value,revision:e.revision});};actions.append(button);}\r\n   input.onkeydown=event=>{if(event.key===\"Enter\"){event.preventDefault();actions.firstChild.click();}};row.append(actions);$(\"demo-rows\").append(row);\r\n  }\r\n }\r\n async function reload(){entries=(await api(\"admin/demos\")).entries;loaded=true;render();}\r\n async function mutate(path,body){if(busy)return;busy=true;document.querySelectorAll(\"#admin-content input,#admin-content button\").forEach(e=>e.disabled=true);status(\"saving\");\r\n  try{await api(path,body);if(path.endsWith('/delete-all'))drafts.clear();else drafts.delete(path.split('/')[2]);await reload();status(\"adminSaved\");}catch(e){statusKey=null;$(\"admin-status\").textContent=e.message;$(\"admin-status\").classList.add(\"error\");}\r\n  finally{busy=false;document.querySelectorAll(\"#admin-content input,#admin-content button\").forEach(e=>e.disabled=false);$(\"delete-demos\").disabled=!entries.length;}\r\n }\r\n $(\"delete-demos\").onclick=()=>{if(confirm(t(\"deleteAllDemosConfirm\")))mutate(\"admin/demos/delete-all\",{confirm:\"DELETE_DEMOS\"});};\r\n $(\"reload-demos\").onclick=async()=>{try{await reload();status(\"adminReady\");}catch(e){statusKey=null;$(\"admin-status\").textContent=e.message;}};\r\n document.addEventListener(\"lod-language\",()=>{if(statusKey)status(statusKey);if(loaded)render();});\r\n window.addEventListener(\"beforeunload\",event=>{if(drafts.size){event.preventDefault();event.returnValue=\"\";}});\r\n (async()=>{try{const {user}=await api(\"me\");if(!user){status(\"adminSignIn\");$(\"admin-login\").hidden=false;return;}if(!user.is_admin){status(\"adminOnly\",true);return;}await reload();$(\"admin-content\").hidden=false;status(\"adminReady\");}catch(e){statusKey=null;$(\"admin-status\").textContent=e.message;$(\"admin-status\").classList.add(\"error\");}})();\r\n})();\r\n","type":"text/javascript; charset=utf-8"},"/admin/new/index.html":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex,nofollow\"><title>League of Doctors · Admin</title><link rel=\"stylesheet\" href=\"/play/play.css\"><link rel=\"stylesheet\" href=\"/play/landing.css\"><link rel=\"stylesheet\" href=\"/admin/admin.css\"><script src=\"/play/locales/ko.js\" defer></script><script src=\"/play/locales/en.js\" defer></script><script src=\"/play/locales/ja.js\" defer></script><script src=\"/play/locales/zh.js\" defer></script><script src=\"/play/locales/es.js\" defer></script><script src=\"/play/locales/it.js\" defer></script><script src=\"/play/locales/fr.js\" defer></script><script src=\"/play/i18n.js\" defer></script><script src=\"/game-core.js\" defer></script><script src=\"/admin/new/create.js\" defer></script></head><body class=\"league-dark\"><header><a class=\"brand\" href=\"/\">League of Doctors</a><select id=\"language\" aria-label=\"Language\"><option value=\"ko\">한국어</option><option value=\"en\">English</option><option value=\"ja\">日本語</option><option value=\"zh\">简体中文</option><option value=\"es\">Español</option><option value=\"it\">Italiano</option><option value=\"fr\">Français</option></select></header><main class=\"admin-main create-main\"><a href=\"/admin/\" data-i18n=\"backToDemos\"></a><h1 data-i18n=\"addDemo\"></h1><p data-i18n=\"createDemoIntro\"></p><p id=\"create-status\" role=\"status\" aria-live=\"polite\"></p><form id=\"create-demo-form\" hidden>\r\n<div class=\"create-grid\"><label><span data-i18n=\"nickname\"></span><input id=\"demo-nickname\" minlength=\"2\" maxlength=\"24\" required autocomplete=\"off\" data-placeholder=\"nicknameHint\"></label>\r\n<label><span data-i18n=\"country\"></span><select id=\"demo-country\" required></select></label>\r\n<label class=\"full-width\"><span data-i18n=\"university\"></span><input id=\"demo-university\" minlength=\"2\" maxlength=\"120\" required autocomplete=\"off\" data-placeholder=\"demoUniversityHint\"></label>\r\n<label><span data-i18n=\"demoScoreLabel\"></span><input id=\"demo-score\" type=\"number\" min=\"0\" max=\"100\" step=\"0.1\" value=\"80\" required></label>\r\n<label><span data-i18n=\"demoRoundsLabel\"></span><input id=\"demo-rounds\" type=\"number\" min=\"1\" max=\"100000\" step=\"1\" value=\"1\" required></label></div>\r\n<p class=\"muted\" data-i18n=\"createDemoHint\"></p><button id=\"create-submit\" class=\"primary\" type=\"submit\" data-i18n=\"createDemo\"></button></form><div id=\"created-actions\" hidden><a href=\"/admin/\" data-i18n=\"backToDemos\"></a></div></main></body></html>","type":"text/html; charset=utf-8"},"/admin/new/create.js":{"content":"\"use strict\";\n(()=>{\n const I=LoDI18n,t=I.t,$=id=>document.getElementById(id),form=$(\"create-demo-form\");\n let busy=false,dirty=false,ready=false,requestId=crypto.randomUUID(),pending=null,statusKey=\"loading\";\n function status(key){statusKey=key;$(\"create-status\").textContent=t(key);$(\"create-status\").classList.remove(\"error\");}\n async function api(path,body){const response=await fetch('/api/'+path,{credentials:'same-origin',method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json();}catch{throw Error(t('badResponse'));}if(!response.ok)throw Object.assign(Error(I.error(data.error)),{status:response.status});return data;}\n function countries(){const old=$(\"demo-country\").value,dn=new Intl.DisplayNames([I.language],{type:\"region\"});$(\"demo-country\").replaceChildren();\n  const option=document.createElement('option');option.value='';option.textContent=t('select');$(\"demo-country\").append(option);\n  PanoGame.countryCodes.map(code=>({code,name:dn.of(code)})).sort((a,b)=>a.name.localeCompare(b.name,I.language)).forEach(c=>{const o=document.createElement('option');o.value=c.code;o.textContent=c.name+' ('+c.code+')';$(\"demo-country\").append(o);});$(\"demo-country\").value=old;\n }\n function freeze(value){busy=value;for(const e of form.elements)e.disabled=value;$(\"create-submit\").textContent=t(value?'saving':'createDemo');}\n form.addEventListener('input',()=>{dirty=true;});\n form.onsubmit=async event=>{\n  event.preventDefault();if(!ready||busy||!form.reportValidity())return;\n  const values={nickname:$(\"demo-nickname\").value,country:$(\"demo-country\").value,university:$(\"demo-university\").value,average:Number($(\"demo-score\").value),rounds:Number($(\"demo-rounds\").value)};\n  // After an ambiguous network error retry the identical operation, not a second record.\n  if(pending&&JSON.stringify(values)!==JSON.stringify(pending)){status('demoRetryOriginal');return;}\n  pending=values;freeze(true);status('saving');\n  try{await api('admin/demos',{...pending,request_id:requestId});dirty=false;pending=null;requestId=crypto.randomUUID();form.reset();status('demoCreated');$(\"created-actions\").hidden=false;}\n  catch(error){if(error.status&&error.status<500){pending=null;if(error.status===409)requestId=crypto.randomUUID();}statusKey=null;$(\"create-status\").textContent=error.message;$(\"create-status\").classList.add('error');}\n  finally{freeze(false);if(pending){for(const e of form.elements)e.disabled=e.id!=='create-submit';$(\"create-submit\").textContent=t('demoRetryCreate');}}\n };\n document.addEventListener('lod-language',()=>{countries();if(statusKey)status(statusKey);});\n window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});\n (async()=>{countries();try{const {user}=await api('me');if(!user?.is_admin){status('adminOnly');return;}ready=true;form.hidden=false;status('createDemoHint');}catch(error){statusKey=null;$(\"create-status\").textContent=error.message;}})();\n})();\n","type":"text/javascript; charset=utf-8"}};
